mapper.select:
SELECT ti.id, ti.tenant_id, ti.course_id, ti.plan_start_date, ti.plan_end_date, ti.actual_start_date, ti.actual_end_date, ti.status, ti.training_location, ti.instructor, (SELECT COUNT(*) FROM shkb_training_participant tp WHERE tp.implementation_id = ti.id AND tp.deleted = 0) AS participant_count, ti.description, ti.url, ti.file_name, ti.content_type, ti.file_size, ti.file_suffix, ti.create_by_id, ti.create_by, ti.create_time, ti.update_by_id, ti.update_by, ti.update_time, ti.deleted, tc.course_name, tc.course_type, tc.training_hours FROM shkb_training_implementation ti LEFT JOIN shkb_training_course tc ON ti.course_id = tc.id WHERE ti.deleted = 0
AND ti.course_id = #{vo.courseId}
AND ti.status = #{vo.status}
AND tc.course_name LIKE CONCAT('%', #{vo.courseName}, '%')
ORDER BY ti.create_time DESC
